-- Additive foundation. Apply only after inspecting the target project's public schema.
begin;
create table public.profiles(id uuid primary key references auth.users(id),display_name text not null default '',disabled boolean not null default false,created_at timestamptz not null default now());
create table public.roles(id text primary key);
create table public.permissions(id text primary key);
create table public.role_permissions(role_id text references public.roles(id),permission_id text references public.permissions(id),primary key(role_id,permission_id));
create table public.user_roles(user_id uuid references public.profiles(id),role_id text references public.roles(id),primary key(user_id,role_id));
insert into public.roles values('owner'),('sales'),('production'),('accounts'),('content'),('customer');
insert into public.permissions select domain||'.'||action from unnest(array['catalog','content','leads','customers','materials','quotations','orders','suppliers','purchases','inventory','workers','production','delivery','finance','reports','settings','users','audit','media']) domain cross join unnest(array['read','write','approve','export']) action;
insert into public.role_permissions select 'owner',id from public.permissions;
insert into public.role_permissions select 'sales',id from public.permissions where id like any(array['leads.%','customers.%','quotations.%','orders.read','catalog.read','materials.read']);
insert into public.role_permissions select 'production',id from public.permissions where id like any(array['production.%','delivery.%','inventory.read','orders.read','workers.read','materials.read']);
insert into public.role_permissions select 'accounts',id from public.permissions where id like any(array['suppliers.%','purchases.%','inventory.read','workers.%','finance.read','finance.write','reports.%','orders.read','customers.read']);
insert into public.role_permissions select 'content',id from public.permissions where id like any(array['catalog.%','content.%','media.%']);
create function public.has_permission(requested text) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.user_roles ur join public.role_permissions rp on rp.role_id=ur.role_id join public.profiles p on p.id=ur.user_id where ur.user_id=auth.uid() and not p.disabled and rp.permission_id=requested)
$$;
create function public.my_permissions() returns text[] language sql stable security definer set search_path='' as $$select coalesce(array_agg(distinct rp.permission_id),'{}') from public.user_roles ur join public.role_permissions rp on rp.role_id=ur.role_id join public.profiles p on p.id=ur.user_id where ur.user_id=auth.uid() and not p.disabled$$;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,display_name) values(new.id,left(coalesce(new.raw_user_meta_data->>'display_name',''),120));insert into public.user_roles values(new.id,'customer');return new;end$$;
create trigger smartfabrication_new_user after insert on auth.users for each row execute function public.handle_new_user();
insert into public.profiles(id,display_name) select id,left(coalesce(raw_user_meta_data->>'display_name',''),120) from auth.users on conflict do nothing;
insert into public.user_roles select id,'customer' from public.profiles on conflict do nothing;

create table public.categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,parent_id uuid references public.categories(id),active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),check(parent_id is distinct from id));
create table public.products(id uuid primary key default gen_random_uuid(),name text not null,sku text not null unique,slug text not null unique,category_id uuid references public.categories(id),description text not null default '',material text not null default 'Mild steel',finish text not null default '',price_min_minor bigint not null default 0 check(price_min_minor>=0),price_max_minor bigint not null default 0,custom_size boolean not null default true,status text not null default 'draft' check(status in('draft','published','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(price_max_minor>=price_min_minor));
create table public.website_sections(id uuid primary key default gen_random_uuid(),name text not null,heading text not null,body text not null default '',status text not null default 'draft' check(status in('draft','published','archived')),sort_order integer not null default 0,created_at timestamptz not null default now());
create table public.media_assets(id uuid primary key default gen_random_uuid(),asset_id text not null unique,public_id text not null unique,resource_type text not null,format text not null,bytes bigint not null check(bytes>0),width integer,height integer,owner_user_id uuid references public.profiles(id),visibility text not null check(visibility in('public','private')),context text not null,created_at timestamptz not null default now());
create table public.product_media(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id),media_id uuid not null references public.media_assets(id),alt_text text not null,sort_order integer not null default 0,created_at timestamptz not null default now());
create table public.gallery_items(id uuid primary key default gen_random_uuid(),name text not null,media_id uuid references public.media_assets(id),category_id uuid references public.categories(id),alt_text text not null,status text not null default 'draft' check(status in('draft','published','archived')),consent_confirmed boolean not null default false,created_at timestamptz not null default now(),check(status<>'published' or consent_confirmed));
create table public.reviews(id uuid primary key default gen_random_uuid(),name text not null,rating integer not null check(rating between 1 and 5),body text not null,status text not null default 'pending' check(status in('pending','published','hidden')),created_at timestamptz not null default now());
create table public.customers(id uuid primary key default gen_random_uuid(),user_id uuid unique references public.profiles(id),name text not null,phone text not null,email text,address text not null default '',notes text not null default '',created_at timestamptz not null default now());
create table public.leads(id uuid primary key default gen_random_uuid(),name text not null,phone text not null,email text,city text not null,requirement text not null,product_id uuid references public.products(id),source text not null default 'direct' check(source in('google','instagram','facebook','whatsapp','direct','referral','other')),status text not null default 'NEW' check(status in('NEW','CONTACTED','REQUIREMENT_CONFIRMED','MEASUREMENT_PENDING','MEASUREMENT_DONE','QUOTATION_SENT','NEGOTIATION','ORDER_CONFIRMED','PRODUCTION','COMPLETED','LOST')),assigned_to uuid references public.profiles(id),customer_id uuid references public.customers(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1);
create index on public.leads(phone,created_at);
create table public.lead_notes(id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.leads(id),note text not null,created_by uuid not null default auth.uid() references public.profiles(id),created_at timestamptz not null default now());
create table public.lead_status_history(id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.leads(id),from_status text,to_status text not null,actor_id uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.follow_ups(id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.leads(id),assigned_to uuid references public.profiles(id),due_at timestamptz not null,note text not null default '',status text not null default 'pending' check(status in('pending','completed')),created_at timestamptz not null default now());
create table public.measurements(id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.leads(id),width_mm numeric not null check(width_mm>0),height_mm numeric not null check(height_mm>0),depth_mm numeric check(depth_mm>0),note text not null default '',verified_by uuid not null default auth.uid() references public.profiles(id),created_at timestamptz not null default now());
create table public.materials(id uuid primary key default gen_random_uuid(),name text not null,code text unique not null,type text not null,size text not null,thickness_mm numeric not null check(thickness_mm>0),unit text not null check(unit in('kg','m','piece','litre','sheet')),weight_kg_per_unit numeric not null check(weight_kg_per_unit>0),reorder_level numeric not null default 0 check(reorder_level>=0),active boolean not null default true,created_at timestamptz not null default now());
create table public.material_rates(id uuid primary key default gen_random_uuid(),material_id uuid not null references public.materials(id),purchase_minor bigint not null check(purchase_minor>=0),selling_minor bigint not null check(selling_minor>=0),effective_at timestamptz not null default now(),currency text not null default 'INR' check(currency='INR'),created_by uuid default auth.uid() references public.profiles(id),created_at timestamptz not null default now());
create table public.bom_versions(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id),version integer not null check(version>0),status text not null default 'draft' check(status in('draft','published','archived')),created_at timestamptz not null default now(),unique(product_id,version));
create table public.bom_items(id uuid primary key default gen_random_uuid(),bom_id uuid not null references public.bom_versions(id),material_id uuid not null references public.materials(id),quantity_per_sq_m numeric not null check(quantity_per_sq_m>0),wastage_percent numeric not null default 5 check(wastage_percent between 0 and 30),created_at timestamptz not null default now(),unique(bom_id,material_id));
create table public.estimate_snapshots(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id),bom_id uuid not null references public.bom_versions(id),input jsonb not null,result jsonb not null,formula_version text not null,created_at timestamptz not null default now());
create table public.quotations(id uuid primary key default gen_random_uuid(),name text not null,lead_id uuid references public.leads(id),customer_id uuid not null references public.customers(id),status text not null default 'draft' check(status in('draft','approved','accepted','rejected','expired')),expires_at timestamptz not null,created_at timestamptz not null default now());
create table public.quotation_versions(id uuid primary key default gen_random_uuid(),quotation_id uuid not null references public.quotations(id),version integer not null check(version>0),snapshot jsonb not null,total_minor bigint not null check(total_minor>0),currency text not null default 'INR' check(currency='INR'),created_at timestamptz not null default now(),unique(quotation_id,version));
create table public.orders(id uuid primary key default gen_random_uuid(),name text not null,quotation_version_id uuid not null unique references public.quotation_versions(id),customer_id uuid not null references public.customers(id),total_minor bigint not null check(total_minor>0),status text not null default 'CONFIRMED' check(status in('CONFIRMED','ADVANCE_RECEIVED','MEASUREMENT_CONFIRMED','PRODUCTION_PENDING','PRODUCTION_STARTED','FABRICATION_COMPLETED','FINISHING','READY','OUT_FOR_DELIVERY','INSTALLATION','COMPLETED','CANCELLED')),due_at timestamptz,note text not null default '',version integer not null default 1,created_at timestamptz not null default now());
create table public.order_status_history(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),from_status text,to_status text not null,note text not null default '',actor_id uuid default auth.uid() references public.profiles(id),created_at timestamptz not null default now());
create table public.customer_payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),amount_minor bigint not null check(amount_minor>0),mode text not null check(mode in('cash','bank','upi','cheque')),reference text not null,idempotency_key uuid not null unique,created_by uuid default auth.uid() references public.profiles(id),created_at timestamptz not null default now());
create table public.suppliers(id uuid primary key default gen_random_uuid(),name text not null,phone text not null,address text not null default '',gst_number text,created_at timestamptz not null default now());
create table public.purchases(id uuid primary key default gen_random_uuid(),name text not null,supplier_id uuid not null references public.suppliers(id),bill_number text not null,bill_date date not null,total_minor bigint not null default 0 check(total_minor>=0),status text not null default 'draft' check(status in('draft','received','cancelled')),created_at timestamptz not null default now(),unique(supplier_id,bill_number));
create table public.purchase_items(id uuid primary key default gen_random_uuid(),purchase_id uuid not null references public.purchases(id),material_id uuid not null references public.materials(id),quantity numeric not null check(quantity>0),rate_minor bigint not null check(rate_minor>=0),created_at timestamptz not null default now());
create table public.supplier_payments(id uuid primary key default gen_random_uuid(),purchase_id uuid not null references public.purchases(id),amount_minor bigint not null check(amount_minor>0),mode text not null check(mode in('cash','bank','upi','cheque')),reference text not null,idempotency_key uuid not null unique,created_at timestamptz not null default now());
create table public.workers(id uuid primary key default gen_random_uuid(),name text not null,phone text not null,work_type text not null,active boolean not null default true,created_at timestamptz not null default now());
create table public.labour_rates(id uuid primary key default gen_random_uuid(),worker_id uuid not null references public.workers(id),unit text not null check(unit in('kg','piece','hour')),rate_minor bigint not null check(rate_minor>0),effective_at timestamptz not null default now(),created_at timestamptz not null default now());
create table public.work_orders(id uuid primary key default gen_random_uuid(),name text not null,order_id uuid not null references public.orders(id),assigned_to uuid references public.profiles(id),status text not null default 'pending' check(status in('pending','fabrication','finishing','quality_check','ready')),planned_weight_kg numeric not null default 0 check(planned_weight_kg>=0),created_at timestamptz not null default now());
create table public.quality_checks(id uuid primary key default gen_random_uuid(),work_order_id uuid not null references public.work_orders(id),name text not null,passed boolean not null,note text not null default '',created_by uuid default auth.uid() references public.profiles(id),created_at timestamptz not null default now());
create table public.stock_movements(id uuid primary key default gen_random_uuid(),material_id uuid not null references public.materials(id),quantity numeric not null check(quantity<>0),unit_cost_minor bigint not null check(unit_cost_minor>=0),kind text not null check(kind in('receipt','consumption','adjustment','return')),purchase_id uuid references public.purchases(id),work_order_id uuid references public.work_orders(id),note text not null,idempotency_key uuid unique not null,created_by uuid default auth.uid() references public.profiles(id),created_at timestamptz not null default now());
create table public.stock_reservations(id uuid primary key default gen_random_uuid(),material_id uuid not null references public.materials(id),work_order_id uuid not null references public.work_orders(id),quantity numeric not null check(quantity>0),status text not null default 'active' check(status in('active','consumed','released')),created_at timestamptz not null default now());
create table public.work_entries(id uuid primary key default gen_random_uuid(),worker_id uuid not null references public.workers(id),work_order_id uuid not null references public.work_orders(id),labour_rate_id uuid not null references public.labour_rates(id),quantity numeric not null check(quantity>0),rate_minor bigint not null check(rate_minor>0),amount_minor bigint not null check(amount_minor>0),status text not null default 'approved' check(status='approved'),created_at timestamptz not null default now());
create table public.labour_payments(id uuid primary key default gen_random_uuid(),worker_id uuid not null references public.workers(id),amount_minor bigint not null check(amount_minor>0),mode text not null check(mode in('cash','bank','upi','cheque')),reference text not null,idempotency_key uuid unique not null,created_at timestamptz not null default now());
create table public.deliveries(id uuid primary key default gen_random_uuid(),name text not null,order_id uuid not null references public.orders(id),scheduled_at timestamptz not null,address text not null,crew text not null,status text not null default 'scheduled' check(status in('scheduled','dispatched','delivered')),proof_media_id uuid references public.media_assets(id),confirmed_at timestamptz,created_at timestamptz not null default now());
create table public.installations(id uuid primary key default gen_random_uuid(),name text not null,delivery_id uuid not null references public.deliveries(id),checklist jsonb not null default '{}',customer_confirmed boolean not null default false,status text not null default 'pending' check(status in('pending','completed')),created_at timestamptz not null default now(),check(status<>'completed' or customer_confirmed));
create table public.expenses(id uuid primary key default gen_random_uuid(),name text not null,category text not null,amount_minor bigint not null check(amount_minor>0),expense_date date not null,mode text not null check(mode in('cash','bank','upi','cheque')),reference text unique not null,order_id uuid references public.orders(id),status text not null default 'draft' check(status in('draft','approved')),created_at timestamptz not null default now());
create table public.owner_withdrawals(id uuid primary key default gen_random_uuid(),name text not null,amount_minor bigint not null check(amount_minor>0),withdrawal_date date not null,mode text not null check(mode in('cash','bank','upi','cheque')),reason text not null,created_by uuid default auth.uid() references public.profiles(id),created_at timestamptz not null default now());
create table public.site_settings(id uuid primary key default gen_random_uuid(),name text unique not null,value text not null,public boolean not null default false,created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),name text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id),action text not null,entity_type text not null,entity_id text,old_status text,new_status text,created_at timestamptz not null default now());

-- Policies intentionally deny all writes to immutable/transactional records outside vetted RPCs.
do $$declare t text; domain text; begin
 for t,domain in select * from (values ('categories','catalog'),('products','catalog'),('product_media','catalog'),('website_sections','content'),('gallery_items','content'),('reviews','content'),('customers','customers'),('leads','leads'),('lead_notes','leads'),('lead_status_history','leads'),('follow_ups','leads'),('measurements','leads'),('materials','materials'),('material_rates','materials'),('bom_versions','materials'),('bom_items','materials'),('estimate_snapshots','materials'),('quotations','quotations'),('quotation_versions','quotations'),('orders','orders'),('order_status_history','orders'),('customer_payments','finance'),('suppliers','suppliers'),('purchases','purchases'),('purchase_items','purchases'),('supplier_payments','finance'),('workers','workers'),('labour_rates','workers'),('work_orders','production'),('quality_checks','production'),('stock_movements','inventory'),('stock_reservations','inventory'),('work_entries','workers'),('labour_payments','finance'),('deliveries','delivery'),('installations','delivery'),('expenses','finance'),('owner_withdrawals','finance'),('site_settings','settings'),('media_assets','media'),('audit_logs','audit')) v(t,domain)
 loop
 execute format('alter table public.%I enable row level security',t);
 execute format('create policy staff_read on public.%I for select to authenticated using(public.has_permission(%L))',t,domain||'.read');
 if t not in('lead_status_history','quotation_versions','orders','order_status_history','customer_payments','material_rates','estimate_snapshots','supplier_payments','stock_movements','stock_reservations','work_entries','labour_payments','owner_withdrawals','audit_logs') then
 execute format('create policy staff_insert on public.%I for insert to authenticated with check(public.has_permission(%L))',t,domain||'.write');
 execute format('create policy staff_update on public.%I for update to authenticated using(public.has_permission(%L)) with check(public.has_permission(%L))',t,domain||'.write',domain||'.write');
 end if;
 end loop;
end$$;
alter table public.profiles enable row level security;
alter table public.roles enable row level security;
alter table public.permissions enable row level security;
alter table public.role_permissions enable row level security;
alter table public.user_roles enable row level security;
alter table public.notifications enable row level security;
create policy own_profile on public.profiles for select to authenticated using(id=auth.uid() or public.has_permission('users.read'));
create policy roles_read on public.roles for select to authenticated using(public.has_permission('users.read'));
create policy permissions_read on public.permissions for select to authenticated using(public.has_permission('users.read'));
create policy role_permissions_read on public.role_permissions for select to authenticated using(public.has_permission('users.read'));
create policy user_roles_read on public.user_roles for select to authenticated using(user_id=auth.uid() or public.has_permission('users.read'));
create policy notifications_own on public.notifications for select to authenticated using(user_id=auth.uid());
create policy notifications_mark_read on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
revoke update on public.notifications from authenticated;
grant update(read_at) on public.notifications to authenticated;
create policy public_categories on public.categories for select to anon,authenticated using(active);
create policy public_products on public.products for select to anon,authenticated using(status='published');
create policy public_sections on public.website_sections for select to anon,authenticated using(status='published');
create policy public_gallery on public.gallery_items for select to anon,authenticated using(status='published' and consent_confirmed);
create policy public_reviews on public.reviews for select to anon,authenticated using(status='published');
create policy public_settings on public.site_settings for select to anon,authenticated using(public);
create policy public_media on public.media_assets for select to anon,authenticated using(visibility='public');
create policy public_product_media on public.product_media for select to anon,authenticated using(exists(select 1 from public.products p where p.id=product_id and p.status='published') and exists(select 1 from public.media_assets m where m.id=media_id and m.visibility='public'));
create policy own_customer on public.customers for select to authenticated using(user_id=auth.uid());
create policy own_quotes on public.quotations for select to authenticated using(exists(select 1 from public.customers c where c.id=customer_id and c.user_id=auth.uid()));
create policy own_quote_versions on public.quotation_versions for select to authenticated using(exists(select 1 from public.quotations q join public.customers c on c.id=q.customer_id where q.id=quotation_id and c.user_id=auth.uid()));
create policy own_orders on public.orders for select to authenticated using(exists(select 1 from public.customers c where c.id=customer_id and c.user_id=auth.uid()));
create policy own_timeline on public.order_status_history for select to authenticated using(exists(select 1 from public.orders o join public.customers c on c.id=o.customer_id where o.id=order_id and c.user_id=auth.uid()));

create function public.audit_change() returns trigger language plpgsql security definer set search_path='' as $$declare old_data jsonb;new_data jsonb;begin
 if TG_OP<>'INSERT' then old_data=to_jsonb(old);end if;if TG_OP<>'DELETE' then new_data=to_jsonb(new);end if;
 insert into public.audit_logs(actor_id,action,entity_type,entity_id,old_status,new_status) values(auth.uid(),TG_OP,TG_TABLE_NAME,coalesce(new_data->>'id',old_data->>'id'),old_data->>'status',new_data->>'status');return coalesce(new,old);end$$;
do $$declare t text;begin for t in select tablename from pg_tables where schemaname='public' and tablename in('products','customers','leads','quotations','quotation_versions','orders','customer_payments','purchases','supplier_payments','stock_movements','work_entries','labour_payments','expenses','owner_withdrawals','user_roles','profiles','site_settings') loop execute format('create trigger audit_mutation after insert or update or delete on public.%I for each row execute function public.audit_change()',t);end loop;end$$;

create function public.submit_lead(payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare result uuid;begin
 perform pg_advisory_xact_lock(731014);
 if length(payload->>'name') not between 2 and 120 or (payload->>'phone')!~ '^\+?[0-9]{10,15}$' or length(payload->>'city') not between 2 and 100 or length(payload->>'requirement') not between 10 and 2000 then raise exception 'Invalid enquiry';end if;
 if (select count(*) from public.leads where phone=payload->>'phone' and created_at>now()-interval '1 hour')>=3 or (select count(*) from public.leads where created_at>now()-interval '1 hour')>=200 then raise exception using errcode='P0001',message='Enquiry limit reached';end if;
 insert into public.leads(name,phone,email,city,requirement,product_id,source) values(payload->>'name',payload->>'phone',nullif(payload->>'email',''),payload->>'city',payload->>'requirement',nullif(payload->>'product_id','')::uuid,coalesce(payload->>'source','direct')) returning id into result;
 insert into public.lead_status_history(lead_id,to_status) values(result,'NEW');
 insert into public.notifications(user_id,name,body) select distinct user_id,'New enquiry','A new enquiry is ready for follow-up.' from public.user_roles where role_id in('owner','sales');return result;end$$;

create function public.record_material_rate(payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare result uuid;begin if not public.has_permission('materials.write') then raise insufficient_privilege;end if;insert into public.material_rates(material_id,purchase_minor,selling_minor,effective_at) values((payload->>'material_id')::uuid,(payload->>'purchase_minor')::bigint,(payload->>'selling_minor')::bigint,coalesce((payload->>'effective_at')::timestamptz,now())) returning id into result;return result;end$$;

create function public.make_quotation_version(target uuid,items jsonb,discount_minor bigint default 0,tax_bps integer default 0) returns uuid language plpgsql security definer set search_path='' as $$declare q public.quotations;v integer;subtotal bigint;total bigint;result uuid;begin
 if not public.has_permission('quotations.write') then raise insufficient_privilege;end if;
 select * into q from public.quotations where id=target for update;if not found then raise no_data_found;end if;
 if q.status<>'draft' then raise exception 'Only draft quotations can be versioned';end if;
 if jsonb_typeof(items)<>'array' or jsonb_array_length(items) not between 1 and 100 or discount_minor<0 or tax_bps not between 0 and 10000 then raise exception 'Invalid quotation lines';end if;
 if exists(select 1 from jsonb_array_elements(items) x where (x->>'quantity')::numeric<=0 or (x->>'unit_minor')::bigint<0 or length(x->>'description') not between 1 and 200) then raise exception 'Invalid quotation line';end if;
 select sum(round((x->>'quantity')::numeric*(x->>'unit_minor')::numeric))::bigint into subtotal from jsonb_array_elements(items) x;
 if discount_minor>subtotal then raise exception 'Discount exceeds subtotal';end if;total=(subtotal-discount_minor)+round((subtotal-discount_minor)::numeric*tax_bps/10000)::bigint;
 select coalesce(max(version),0)+1 into v from public.quotation_versions where quotation_id=target;
 insert into public.quotation_versions(quotation_id,version,snapshot,total_minor) values(target,v,jsonb_build_object('items',items,'subtotal_minor',subtotal,'discount_minor',discount_minor,'tax_bps',tax_bps,'total_minor',total),total) returning id into result;return result;end$$;

create function public.approve_quotation(target uuid) returns void language plpgsql security definer set search_path='' as $$begin if not public.has_permission('quotations.approve') then raise insufficient_privilege;end if;perform 1 from public.quotations where id=target and status='draft' and expires_at>now() for update;if not found then raise exception 'Quotation cannot be approved';end if;if not exists(select 1 from public.quotation_versions where quotation_id=target) then raise exception 'Quotation needs a version';end if;update public.quotations set status='approved' where id=target;end$$;
create function public.respond_quotation(target uuid,accepted boolean) returns void language plpgsql security definer set search_path='' as $$begin perform 1 from public.quotations q join public.customers c on c.id=q.customer_id where q.id=target and q.status='approved' and q.expires_at>now() and (c.user_id=auth.uid() or public.has_permission('quotations.approve')) for update of q;if not found then raise exception 'Quotation cannot be accepted or rejected';end if;update public.quotations set status=case when accepted then 'accepted' else 'rejected' end where id=target;end$$;
create function public.convert_quotation(target uuid) returns uuid language plpgsql security definer set search_path='' as $$declare q public.quotations;v public.quotation_versions;result uuid;begin
 if not public.has_permission('orders.write') then raise insufficient_privilege;end if;select * into q from public.quotations where id=target for update;if not found then raise no_data_found;end if;
 select * into v from public.quotation_versions where quotation_id=q.id order by version desc limit 1;select id into result from public.orders where quotation_version_id=v.id;if result is not null then return result;end if;
 if q.status<>'accepted' then raise exception 'Accepted quotation required';end if;
 insert into public.orders(name,quotation_version_id,customer_id,total_minor) values(q.name,v.id,q.customer_id,v.total_minor) returning id into result;insert into public.order_status_history(order_id,to_status) values(result,'CONFIRMED');return result;end$$;

create function public.post_stock(payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare material uuid;qty numeric;balance numeric;reserved numeric;result uuid;existing public.stock_movements;kind text;begin
 material=(payload->>'material_id')::uuid;qty=(payload->>'quantity')::numeric;kind=payload->>'kind';
 if not public.has_permission(case when kind='consumption' then 'production.write' else 'inventory.approve' end) then raise insufficient_privilege;end if;
 perform 1 from public.materials where id=material for update;if not found then raise no_data_found;end if;
 select * into existing from public.stock_movements where idempotency_key=(payload->>'idempotency_key')::uuid;if found then if existing.material_id<>material or existing.quantity<>qty or existing.kind<>kind then raise exception 'Idempotency key conflict';end if;return existing.id;end if;
 if kind not in('adjustment','consumption','return') or qty=0 or (kind='consumption' and (qty>=0 or nullif(payload->>'work_order_id','') is null)) then raise exception 'Invalid stock movement';end if;
 select coalesce(sum(quantity),0) into balance from public.stock_movements where material_id=material;
 select coalesce(sum(quantity),0) into reserved from public.stock_reservations where material_id=material and status='active' and (kind<>'consumption' or work_order_id is distinct from nullif(payload->>'work_order_id','')::uuid);
 if balance+qty<reserved then raise exception 'Insufficient available stock';end if;
 insert into public.stock_movements(material_id,quantity,unit_cost_minor,kind,work_order_id,note,idempotency_key) values(material,qty,(payload->>'unit_cost_minor')::bigint,kind,nullif(payload->>'work_order_id','')::uuid,payload->>'note',(payload->>'idempotency_key')::uuid) returning id into result;
 if kind='consumption' then update public.stock_reservations set status='consumed' where material_id=material and work_order_id=(payload->>'work_order_id')::uuid and status='active';end if;return result;end$$;

create function public.receive_purchase(target uuid) returns void language plpgsql security definer set search_path='' as $$declare p public.purchases;item record;total bigint;begin
 if not public.has_permission('purchases.approve') then raise insufficient_privilege;end if;select * into p from public.purchases where id=target for update;if not found then raise no_data_found;end if;if p.status='received' then return;end if;if p.status<>'draft' then raise exception 'Purchase is not receivable';end if;
 if not exists(select 1 from public.purchase_items where purchase_id=target) then raise exception 'Purchase needs line items';end if;
 for item in select * from public.purchase_items where purchase_id=target order by material_id loop perform 1 from public.materials where id=item.material_id for update;insert into public.stock_movements(material_id,quantity,unit_cost_minor,kind,purchase_id,note,idempotency_key) values(item.material_id,item.quantity,item.rate_minor,'receipt',target,'Purchase receipt',gen_random_uuid());end loop;
 select sum(round(quantity*rate_minor))::bigint into total from public.purchase_items where purchase_id=target;update public.purchases set status='received',total_minor=total where id=target;end$$;

create function public.reserve_stock(payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare result uuid;balance numeric;reserved numeric;material uuid;qty numeric;begin
 if not public.has_permission('production.write') then raise insufficient_privilege;end if;material=(payload->>'material_id')::uuid;qty=(payload->>'quantity')::numeric;perform 1 from public.materials where id=material for update;
 select coalesce(sum(quantity),0) into balance from public.stock_movements where material_id=material;select coalesce(sum(quantity),0) into reserved from public.stock_reservations where material_id=material and status='active';if qty<=0 or balance-reserved<qty then raise exception 'Insufficient available stock';end if;
 insert into public.stock_reservations(material_id,work_order_id,quantity) values(material,(payload->>'work_order_id')::uuid,qty) returning id into result;return result;end$$;

create function public.post_work_entry(payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare rate public.labour_rates;result uuid;qty numeric;begin
 if not public.has_permission('workers.approve') then raise insufficient_privilege;end if;qty=(payload->>'quantity')::numeric;select * into rate from public.labour_rates where worker_id=(payload->>'worker_id')::uuid and effective_at<=now() order by effective_at desc,created_at desc limit 1;if not found then raise exception 'Worker has no current rate';end if;
 insert into public.work_entries(worker_id,work_order_id,labour_rate_id,quantity,rate_minor,amount_minor) values(rate.worker_id,(payload->>'work_order_id')::uuid,rate.id,qty,rate.rate_minor,round(qty*rate.rate_minor)) returning id into result;return result;end$$;

create function public.post_payment(payment_kind text,payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare result uuid;amount bigint;total bigint;paid bigint;target uuid;table_name text;field_name text;existing record;begin
 if not public.has_permission('finance.write') then raise insufficient_privilege;end if;amount=(payload->>'amount_minor')::bigint;if amount<=0 then raise exception 'Positive payment required';end if;
 if payment_kind='customer' then table_name='customer_payments';field_name='order_id';elsif payment_kind='supplier' then table_name='supplier_payments';field_name='purchase_id';elsif payment_kind='labour' then table_name='labour_payments';field_name='worker_id';else raise exception 'Invalid payment kind';end if;
 target=(payload->>field_name)::uuid;perform pg_advisory_xact_lock(hashtextextended(target::text,0));
 execute format('select id,%I as target,amount_minor from public.%I where idempotency_key=$1',field_name,table_name) into existing using (payload->>'idempotency_key')::uuid;
 if existing.id is not null then if existing.target<>target or existing.amount_minor<>amount then raise exception 'Idempotency key conflict';end if;return existing.id;end if;
 if payment_kind='customer' then select total_minor into total from public.orders where id=target;
 elsif payment_kind='supplier' then select total_minor into total from public.purchases where id=target and status='received';
 else select coalesce(sum(amount_minor),0) into total from public.work_entries where worker_id=target;end if;
 if total is null then raise exception 'Payment target not found or not posted';end if;
 execute format('select coalesce(sum(amount_minor),0) from public.%I where %I=$1',table_name,field_name) into paid using target;if paid+amount>total then raise exception 'Payment exceeds outstanding balance';end if;
 execute format('insert into public.%I(%I,amount_minor,mode,reference,idempotency_key) values($1,$2,$3,$4,$5) returning id',table_name,field_name) into result using target,amount,payload->>'mode',payload->>'reference',(payload->>'idempotency_key')::uuid;return result;end$$;

create function public.record_withdrawal(payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare result uuid;begin if not public.has_permission('finance.approve') then raise insufficient_privilege;end if;insert into public.owner_withdrawals(name,amount_minor,withdrawal_date,mode,reason) values(payload->>'name',(payload->>'amount_minor')::bigint,(payload->>'withdrawal_date')::date,payload->>'mode',payload->>'reason') returning id into result;return result;end$$;

create function public.set_user_role(target uuid,role_name text,enabled boolean) returns void language plpgsql security definer set search_path='' as $$begin if not public.has_permission('users.write') then raise insufficient_privilege;end if;if target=auth.uid() and role_name='owner' and not enabled then raise exception 'Cannot remove your own owner role';end if;if enabled then insert into public.user_roles values(target,role_name) on conflict do nothing;else delete from public.user_roles where user_id=target and role_id=role_name;end if;end$$;

-- Guard workflow fields even when callers access Supabase tables directly.
create function public.protect_business_updates() returns trigger language plpgsql set search_path='' as $$begin
 if TG_TABLE_NAME='quotations' and old.status<>new.status and current_user in('authenticated','anon') then raise exception 'Use quotation workflow';end if;
 if TG_TABLE_NAME='leads' and old.status<>new.status then raise exception 'Use lead transition function';end if;
 if TG_TABLE_NAME='purchases' and (old.status<>new.status or old.total_minor<>new.total_minor) and current_user in('authenticated','anon') then raise exception 'Use purchase workflow';end if;
 if TG_TABLE_NAME='purchase_items' and exists(select 1 from public.purchases where id=coalesce(new.purchase_id,old.purchase_id) and status<>'draft') then raise exception 'Posted purchase items are immutable';end if;
 if TG_TABLE_NAME='expenses' and old.status='approved' then raise exception 'Approved expenses are immutable';end if;
 if TG_TABLE_NAME='bom_items' and exists(select 1 from public.bom_versions where id=coalesce(new.bom_id,old.bom_id) and status='published') then raise exception 'Published BOM is immutable';end if;
 return new;end$$;
create trigger protect_quotes before update on public.quotations for each row execute function public.protect_business_updates();
create trigger protect_leads before update on public.leads for each row execute function public.protect_business_updates();
create trigger protect_purchases before update on public.purchases for each row execute function public.protect_business_updates();
create trigger protect_purchase_items before update on public.purchase_items for each row execute function public.protect_business_updates();
create trigger protect_expenses before update on public.expenses for each row execute function public.protect_business_updates();
create trigger protect_bom_items before update on public.bom_items for each row execute function public.protect_business_updates();

-- Revoke default public execution; each client-callable function is granted explicitly.
revoke execute on all functions in schema public from public;
grant execute on function public.has_permission(text),public.my_permissions() to authenticated;
grant execute on function public.submit_lead(jsonb) to anon,authenticated;
grant execute on function public.record_material_rate(jsonb),public.make_quotation_version(uuid,jsonb,bigint,integer),public.approve_quotation(uuid),public.respond_quotation(uuid,boolean),public.convert_quotation(uuid),public.post_stock(jsonb),public.receive_purchase(uuid),public.reserve_stock(jsonb),public.post_work_entry(jsonb),public.post_payment(text,jsonb),public.record_withdrawal(jsonb),public.set_user_role(uuid,text,boolean) to authenticated;
grant select on all tables in schema public to anon,authenticated;
grant insert,update on public.categories,public.products,public.product_media,public.website_sections,public.gallery_items,public.reviews,public.customers,public.leads,public.lead_notes,public.follow_ups,public.measurements,public.materials,public.bom_versions,public.bom_items,public.quotations,public.suppliers,public.purchases,public.purchase_items,public.workers,public.labour_rates,public.work_orders,public.quality_checks,public.deliveries,public.installations,public.expenses,public.site_settings,public.media_assets to authenticated;
commit;
